// ══════════════════════════════════════════════════════
// DOME GALLERY (React Bits) · port del mecanismo real: 35 columnas
// × 5 filas de mosaicos sobre una esfera CSS 3D (cada uno rota en
// Y/X y se empuja con translateZ(radio)); arrastrar rota la esfera
// (sensibilidad 20, ±5° en vertical) y al soltar sigue por inercia
// con la misma fricción del original. Clic abre el mosaico con el
// mismo FLIP del original (del rectángulo del mosaico al marco
// centrado) y lo regresa al cerrar. Cambios: eventos de puntero
// nativos en vez de @use-gesture, sin bloqueo del scroll de la
// página (vive dentro de un panel), y a color (grayscale:false) por
// ser un collage con color. Las imágenes son recortes de
// prouned_metro/_dark hasta tener imágenes propias para la galería.
// ══════════════════════════════════════════════════════
import { changeListeners, drawBg, rebuildNodes, reduceMotion, updateHexes } from './kit.js';
import { initHero, updateHeroImage } from './hero.js';
import { initCursorGrid } from './cursor-grid.js';
import { initWarpText } from './warp-text.js';
import { initBorderGlow } from './border-glow.js';
import { initLoaderDemo } from './lattice-loader.js';
import { initDock } from './dock.js';

export let domeReady = false;
export function initDome() {
  if (domeReady) return;
  const root = document.getElementById('metro-dome');
  if (!root) return;
  domeReady = true;
  const SEG = 35, MAX_VERT = 5, SENS = 20, DAMP = 1, FIT = 0.75, MIN_R = 600, PAD = 0.25, ENLARGE_MS = 300;
  const urls = METRO_TILES.map(b64 => {
    const bin = atob(b64), u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([u8], { type: 'image/webp' }));
  });
  const xCols = Array.from({ length: SEG }, (_, i) => -37 + i * 2);
  const coords = xCols.flatMap((x, c) => (c % 2 === 0 ? [-4, -2, 0, 2, 4] : [-3, -1, 1, 3, 5]).map(y => ({ x, y })));
  const used = coords.map((_, i) => i % urls.length);
  for (let i = 1; i < used.length; i++) if (used[i] === used[i - 1]) for (let j = i + 1; j < used.length; j++) if (used[j] !== used[i]) { [used[i], used[j]] = [used[j], used[i]]; break; }

  root.style.setProperty('--segments-x', SEG); root.style.setProperty('--segments-y', SEG);
  root.innerHTML = `<div class="dg-main"><div class="dg-stage"><div class="dg-sphere"></div></div><div class="dg-overlay"></div><div class="dg-overlay dg-overlay-blur"></div><div class="dg-edge-fade top"></div><div class="dg-edge-fade bottom"></div><div class="dg-viewer"><div class="dg-scrim"></div><div class="dg-frame"></div></div></div>`;
  const main = root.querySelector('.dg-main'), sphere = root.querySelector('.dg-sphere'), viewer = root.querySelector('.dg-viewer'), frame = root.querySelector('.dg-frame'), scrim = root.querySelector('.dg-scrim');
  const frag = document.createDocumentFragment();
  coords.forEach((c, i) => {
    const it = document.createElement('div');
    it.className = 'dg-item'; it.dataset.offsetX = c.x; it.dataset.offsetY = c.y; it.dataset.src = urls[used[i]];
    it.style.setProperty('--offset-x', c.x); it.style.setProperty('--offset-y', c.y);
    it.style.setProperty('--item-size-x', 2); it.style.setProperty('--item-size-y', 2);
    const tile = document.createElement('div');
    tile.className = 'dg-item-image'; tile.setAttribute('role', 'button'); tile.tabIndex = 0; tile.setAttribute('aria-label', 'Abrir imagen ' + (used[i] + 1));
    const img = document.createElement('img'); img.src = urls[used[i]]; img.alt = ''; img.draggable = false; img.decoding = 'async';
    tile.appendChild(img); it.appendChild(tile); frag.appendChild(it);
  });
  sphere.appendChild(frag);

  const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
  const wrapSigned = d => ((((d + 180) % 360) + 360) % 360) - 180;
  const norm = d => ((d % 360) + 360) % 360;
  let rot = { x: 0, y: 0 };
  const apply = () => { sphere.style.transform = `translateZ(calc(var(--radius) * -1)) rotateX(${rot.x}deg) rotateY(${rot.y}deg)`; };
  new ResizeObserver(([en]) => {
    const w = Math.max(1, en.contentRect.width), h = Math.max(1, en.contentRect.height);
    const minDim = Math.min(w, h), basis = w / h >= 1.3 ? w : minDim;
    const radius = Math.round(clamp(Math.min(basis * FIT, h * 2.2), MIN_R, Infinity));
    root.style.setProperty('--radius', radius + 'px');
    root.style.setProperty('--viewer-pad', Math.max(8, Math.round(minDim * PAD)) + 'px');
    apply();
  }).observe(root);

  // Arrastre + inercia (misma fricción y umbrales del original, DAMP=1 es dragDampening=2 recortado a [0,1]).
  let inertia = 0, dragging = false, moved = false, start = null, startRot = null, lastDragEnd = 0, samples = [];
  const stopInertia = () => { cancelAnimationFrame(inertia); inertia = 0; };
  function startInertia(vx, vy) {
    let vX = clamp(vx, -1.4, 1.4) * 80, vY = clamp(vy, -1.4, 1.4) * 80, frames = 0;
    const fr = 0.94 + 0.055 * DAMP, stop = 0.015 - 0.01 * DAMP, maxF = Math.round(90 + 270 * DAMP);
    const step = () => {
      vX *= fr; vY *= fr;
      if ((Math.abs(vX) < stop && Math.abs(vY) < stop) || ++frames > maxF) { inertia = 0; return; }
      rot = { x: clamp(rot.x - vY / 200, -MAX_VERT, MAX_VERT), y: wrapSigned(rot.y + vX / 200) };
      apply(); inertia = requestAnimationFrame(step);
    };
    stopInertia(); inertia = requestAnimationFrame(step);
  }
  let focused = null, opening = false, openedAt = 0, origPos = null;
  main.addEventListener('pointerdown', e => {
    if (focused || e.button !== 0) return;
    stopInertia(); dragging = true; moved = false;
    start = { x: e.clientX, y: e.clientY }; startRot = { ...rot }; samples = [{ x: e.clientX, y: e.clientY, t: performance.now() }];
  });
  window.addEventListener('pointermove', e => {
    if (!dragging || focused) return;
    const dx = e.clientX - start.x, dy = e.clientY - start.y;
    if (!moved && dx * dx + dy * dy > 16) { moved = true; main.classList.add('is-dragging'); main.setPointerCapture?.(e.pointerId); }
    if (!moved) return;
    rot = { x: clamp(startRot.x - dy / SENS, -MAX_VERT, MAX_VERT), y: wrapSigned(startRot.y + dx / SENS) };
    apply();
    samples.push({ x: e.clientX, y: e.clientY, t: performance.now() });
    if (samples.length > 5) samples.shift();
  });
  window.addEventListener('pointerup', () => {
    if (!dragging) return;
    dragging = false; main.classList.remove('is-dragging');
    if (moved && !reduceMotion.matches) {
      const a = samples[0], b = samples[samples.length - 1], dt = Math.max(1, b.t - a.t);
      const vx = (b.x - a.x) / dt, vy = (b.y - a.y) / dt;
      if (Math.abs(vx) > 0.005 || Math.abs(vy) > 0.005) startInertia(vx, vy);
      lastDragEnd = performance.now();
    }
    setTimeout(() => { moved = false; }, 0);
  });

  const baseRot = (ox, oy) => { const unit = 360 / SEG / 2; return { rotateX: unit * (oy - 0.5), rotateY: unit * (ox + 0.5) }; };
  function open(tile) {
    if (opening || focused) return;
    opening = true; openedAt = performance.now();
    const parent = tile.parentElement;
    focused = tile;
    const pr = baseRot(+parent.dataset.offsetX, +parent.dataset.offsetY);
    let rotY = -(norm(pr.rotateY) + norm(rot.y)) % 360; if (rotY < -180) rotY += 360;
    const rotX = -pr.rotateX - rot.x;
    parent.style.setProperty('--rot-y-delta', rotY + 'deg');
    parent.style.setProperty('--rot-x-delta', rotX + 'deg');
    const ref = document.createElement('div');
    ref.className = 'dg-item-image dg-ref'; ref.style.opacity = '0';
    ref.style.transform = `rotateX(${-pr.rotateX}deg) rotateY(${-pr.rotateY}deg)`;
    parent.appendChild(ref); void ref.offsetHeight;
    const tR = ref.getBoundingClientRect(), mR = main.getBoundingClientRect(), fR = frame.getBoundingClientRect();
    if (tR.width <= 0 || fR.width <= 0) { opening = false; focused = null; ref.remove(); return; }
    origPos = { left: tR.left, top: tR.top, width: tR.width, height: tR.height, ref };
    tile.style.visibility = 'hidden';
    const ov = document.createElement('div');
    ov.className = 'dg-enlarge';
    Object.assign(ov.style, { left: (fR.left - mR.left) + 'px', top: (fR.top - mR.top) + 'px', width: fR.width + 'px', height: fR.height + 'px', opacity: '0', transition: `transform ${ENLARGE_MS}ms ease, opacity ${ENLARGE_MS}ms ease` });
    const img = document.createElement('img'); img.src = parent.dataset.src; img.alt = tile.getAttribute('aria-label');
    ov.appendChild(img); viewer.appendChild(ov);
    ov.style.transform = `translate(${tR.left - fR.left}px, ${tR.top - fR.top}px) scale(${tR.width / fR.width}, ${tR.height / fR.height})`;
    setTimeout(() => { ov.style.opacity = '1'; ov.style.transform = 'translate(0,0) scale(1,1)'; root.setAttribute('data-enlarging', 'true'); opening = false; }, 16);
  }
  function close() {
    if (performance.now() - openedAt < 250) return;
    const el = focused; if (!el) return;
    const parent = el.parentElement, ov = viewer.querySelector('.dg-enlarge');
    if (!ov || !origPos) return;
    const cR = ov.getBoundingClientRect(), rR = root.getBoundingClientRect();
    const anim = document.createElement('div');
    anim.className = 'dg-enlarge-closing';
    anim.style.cssText = `position:absolute;left:${cR.left - rR.left}px;top:${cR.top - rR.top}px;width:${cR.width}px;height:${cR.height}px;z-index:9999;border-radius:var(--enlarge-radius);overflow:hidden;transition:all ${ENLARGE_MS}ms ease-out;pointer-events:none;`;
    anim.appendChild(ov.querySelector('img').cloneNode());
    ov.remove(); root.appendChild(anim); void anim.offsetWidth;
    const o = origPos;
    requestAnimationFrame(() => { Object.assign(anim.style, { left: (o.left - rR.left) + 'px', top: (o.top - rR.top) + 'px', width: o.width + 'px', height: o.height + 'px', opacity: '0' }); });
    root.removeAttribute('data-enlarging');
    const done = () => {
      anim.remove(); o.ref.remove(); origPos = null;
      parent.style.transition = 'none';
      parent.style.setProperty('--rot-y-delta', '0deg'); parent.style.setProperty('--rot-x-delta', '0deg');
      requestAnimationFrame(() => {
        el.style.visibility = ''; el.style.opacity = '0'; focused = null;
        requestAnimationFrame(() => { parent.style.transition = ''; el.style.transition = 'opacity 300ms ease-out'; el.style.opacity = '1'; setTimeout(() => { el.style.transition = ''; el.style.opacity = ''; }, 300); });
      });
    };
    anim.addEventListener('transitionend', done, { once: true });
    setTimeout(() => { if (anim.isConnected) done(); }, ENLARGE_MS + 200);
  }
  sphere.addEventListener('click', e => {
    const tile = e.target.closest('.dg-item-image');
    if (!tile || tile.classList.contains('dg-ref') || moved || dragging || performance.now() - lastDragEnd < 80) return;
    open(tile);
  });
  sphere.addEventListener('keydown', e => {
    const tile = e.target.closest('.dg-item-image');
    if (tile && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); open(tile); }
  });
  scrim.addEventListener('click', close);
  window.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
}
// ── Init ───────────────────────────────────────────────
export let warpFx = null;
// Recortes de prouned_metro / prouned_metro_dark (360×360, WebP) para la galería.
export const METRO_TILES = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
];
export function mount() {
changeListeners.push(() => { updateHeroImage(); if (warpFx) warpFx.rasterize(); });
window.addEventListener('resize', rebuildNodes);
rebuildNodes();
updateHexes();
requestAnimationFrame(drawBg);
initCursorGrid();
initHero();
warpFx = initWarpText();
initBorderGlow();
initLoaderDemo();
initDock();
}
